import { handleReleaseCatalog } from "./lib/release-cache";
import { withSiteLanguage } from "./lib/language-routing";
import { handleConsole } from "./lib/console-route";
// @ts-expect-error Generated by OpenNext before Wrangler bundles this entry.
import next from "./.open-next/worker.js";
import { handleCore, RelayRoom, type CoreEnv } from "@reignhub/worker-core";
export { RelayRoom };
export default {
  async fetch(
    request: Request,
    env: CoreEnv & { ASSETS: Fetcher },
    ctx: ExecutionContext,
  ) {
    const console = await handleConsole(request, env);
    if (console) return console;
    return withSiteLanguage(
      request,
      async () =>
        (await handleReleaseCatalog(request, env, ctx)) ??
        (await handleCore(request, env)) ??
        next.fetch(request, env, ctx),
    );
  },
  async scheduled(_event: ScheduledController, env: CoreEnv) {
    await env.DB.prepare("DELETE FROM pairings WHERE expires < ?")
      .bind(Math.floor(Date.now() / 1000) - 86400)
      .run();
  },
};
